impl<St, S: BosStr> MethodBuilder<St, S>
where
    St: method_state::State,
    St::Lexicon: method_state::IsUnset,
{
    /// Set the `lexicon` field (required)
    pub fn lexicon(
        mut self,
        value: impl Into<AtUri<S>>,
    ) -> MethodBuilder<method_state::SetLexicon<St>, S> {
        self._fields.2 = Option::Some(value.into());
        MethodBuilder {
            _state: PhantomData,
            _fields: self._fields,
            _type: PhantomData,
        }
    }
}

impl<St, S: BosStr> MethodBuilder<St, S>
where
    St: method_state::State,
    St::Lexicon: method_state::IsSet,
{
    /// Build the final struct.
    pub fn build(self) -> Method<S> {
        Method {
            auth_methods: self._fields.0,
            deprecated: self._fields.1,
            lexicon: self._fields.2.unwrap(),
            extra_data: Default::default(),
        }
    }
    /// Build the final struct with custom extra_data.
    pub fn build_with_data(self, extra_data: BTreeMap<SmolStr, Data<S>>) -> Method<S> {
        Method {
            auth_methods: self._fields.0,
            deprecated: self._fields.1,
            lexicon: self._fields.2.unwrap(),
            extra_data: Some(extra_data),
        }
    }
}

fn deserialize_url_template_extra_data<'de, S, D>(
    deserializer: D,
) -> Result<Option<BTreeMap<SmolStr, Data<S>>>, D::Error>
where
    S: BosStr + serde::Deserialize<'de>,
    D: serde::Deserializer<'de>,
{
    let data =
        <Option<BTreeMap<SmolStr, Data<S>>> as serde::Deserialize<'de>>::deserialize(deserializer)?;
    Ok(data.filter(|extra_data| !extra_data.is_empty()))
}
